mapper.insert:
insert into lecture(
	lecture_no, lecture_title, lecture_category, 
	lecture_duration, lecture_price, lecture_type
)
values(
	#{lectureNo}, #{lectureTitle}, #{lectureCategory}
	,#{lectureDuration}, #{lecturePrice}, #{lectureType}
)

mapper.select:
select * from (
	select rownum rn, TMP.* from (
		select * from lecture



			where lecture_no < #{lastLectureNo}


		order by lecture_no desc
	)TMP			
) where rn between 1 and #{size}


with temp_list as (
select rownum rn, TMP.* from(
	select * from lecture





and lecture_category in 

		#{lectureCategory}




	and instr(lecture_title, #{lectureTitle}) > 0



and lecture_type in

		#{lectureType}





		and lecture_duration between #{minLectureDuration} and #{maxLectureDuration}



	and lecture_duration >= #{minLectureDuration}




	and lecture_duration <= #{maxLectureDuration}






		and lecture_price between #{minLecturePrice} and #{maxLecturePrice}



	and lecture_price >= #{minLecturePrice}




	and lecture_price <= #{maxLecturePrice}





order by


		${order},


		lecture_no desc
	)TMP
)
select * from(
	select * from temp_list 

	 where rn > (select rn from temp_list WHERE lecture_no = #{lectureNo}) 

) 

where rownum <= #{size}


with temp_list as (
select rownum rn, TMP.* from(
	select * from lecture





and lecture_category in 

		#{lectureCategory}




	and instr(lecture_title, #{lectureTitle}) > 0



and lecture_type in

		#{lectureType}





		and lecture_duration between #{minLectureDuration} and #{maxLectureDuration}



	and lecture_duration >= #{minLectureDuration}




	and lecture_duration <= #{maxLectureDuration}






		and lecture_price between #{minLecturePrice} and #{maxLecturePrice}



	and lecture_price >= #{minLecturePrice}




	and lecture_price <= #{maxLecturePrice}





order by


		${order},


		lecture_no desc
	)TMP
)
select count(*) from(
	select * from temp_list 

	 where rn > (select rn from temp_list WHERE lecture_no = #{lectureNo}) 

)
